CREATE TABLE t1(a,b,c PRIMARY KEY) WITHOUT ROWID; CREATE INDEX t1a ON t1(a) WHERE a IS NOT NULL; CREATE INDEX t1b ON t1(b) WHERE b>10; WITH RECURSIVE nums(value) AS (VALUES(1) UNION ALL SELECT value+1 FROM nums WHERE value<20) INSERT INTO t1(a,b,c) SELECT CASE WHEN value%3!=0 THEN value END, value, value FROM nums; CREATE INDEX bad1 ON t1(a,b) WHERE a NOT LIKE 'abc%'; INSERT INTO t1(a,b,c) VALUES('abcde',1,101),('abdef',2,102),('xyz',3,103),('abcz',4,104);